fn is_ascii_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    for c in s.chars() {
        if !is_ascii_digit(c) {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_ascii_digit() {
        for c in '0'..='9' {
            assert!(is_ascii_digit(c));
        }
        assert!(!is_ascii_digit('a'));
        assert!(!is_ascii_digit(' '));
        assert!(!is_ascii_digit('𝟘')); // Unicode digit zero
    }

    #[test]
    fn test_all_digits() {
        assert!(all_digits("".to_string()));
        assert!(all_digits("0123456789".to_string()));
        assert!(!all_digits("1234a567".to_string()));
        assert!(!all_digits("１２３".to_string())); // fullwidth digits
        assert!(!all_digits("0💖9".to_string()));
    }
}